import { useState, useEffect, useMemo, useCallback, useRef, createContext, useContext } from 'react'
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  type Node,
  type Edge,
  type NodeTypes,
  Handle,
  Position,
  BackgroundVariant,
  ReactFlowProvider,
  getNodesBounds,
  getViewportForBounds,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { toPng } from 'html-to-image'
import {
  Users, Search, Cpu, Paintbrush, BarChart3, Shield,
  X, ChevronDown, ChevronRight, Network, LayoutGrid, List, Camera,
  Maximize2, Minimize2, Crown, AlertTriangle, Settings, Check,
} from 'lucide-react'
import { toast } from '../components/Toast'
import { getOrgChart, getDrift, getDepartments, updateOrgAgent, getGlobalAgents, subscribeOrgChart } from '../lib/api'
import type { OrgChartData, OrgChartNode, DriftData, OrgAgentPatch } from '../lib/api'
import type { Agent } from '../types'
import LevelBadge, { levelColors } from '../components/LevelBadge'
import AgentIcon from '../components/AgentIcon'

// ── Constants ────────────────────────────────────────────────────────────────

// Department view constants
const DEPT_WIDTH = 340
const DEPT_HEADER_HEIGHT = 68
const DEPT_PADDING_Y = 14
const MEMBER_ROW_HEIGHT = 90
const MEMBER_ROW_GAP = 6
const DEPT_ROW_GAP = 36
const LEADER_WIDTH = 260
const LEADER_HEIGHT = 96
const LEADER_DEPT_GAP = 90
const LEADER_LEADER_GAP = 64

// Context for selecting a member from inside a DepartmentNode
// (avoids passing callbacks through node.data which causes re-render churn)
const OrgSelectContext = createContext<{
  selectedId: string | null
  onSelect: (id: string) => void
}>({ selectedId: null, onSelect: () => {} })

const TIER_ICONS: Record<string, typeof Cpu> = {
  leadership: Shield,
  engineer: Cpu,
  analyst: BarChart3,
  creative: Paintbrush,
}

const MODEL_BADGES: Record<string, { label: string; bg: string; text: string; border: string }> = {
  opus: { label: 'Opus', bg: 'rgba(168,85,247,0.15)', text: '#c084fc', border: 'rgba(168,85,247,0.3)' },
  sonnet: { label: 'Sonnet', bg: 'rgba(96,165,250,0.15)', text: '#60a5fa', border: 'rgba(96,165,250,0.3)' },
  haiku: { label: 'Haiku', bg: 'rgba(52,211,153,0.15)', text: '#34d399', border: 'rgba(52,211,153,0.3)' },
}

function extractEmoji(name: string): { emoji: string; cleanName: string } {
  const emoji = name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
  const cleanName = name
    .replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '')
    .replace(/^—\s*/, '')
    .trim()
  return { emoji, cleanName: cleanName.split('—')[0]?.trim() || cleanName }
}

// ── Department Layout Algorithm ──────────────────────────────────────────────

interface MemberInfo {
  id: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  reportsTo: string | null
  dimmed: boolean
  level?: number | null
  levelTitle?: string | null
  yearsOfExperience?: number | null
  status?: 'active' | 'probation' | 'pip' | 'retired'
}

interface DepartmentNodeData {
  phase: string
  phaseLabel: string
  phaseColor: string
  members: MemberInfo[]
  width: number
  height: number
  dimmed: boolean
  [key: string]: unknown
}

interface LeaderNodeData {
  id: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  description: string
  dimmed: boolean
  [key: string]: unknown
}

function toMemberInfo(node: OrgChartNode): MemberInfo {
  const { emoji, cleanName } = extractEmoji(node.name)
  return {
    id: node.id,
    name: cleanName,
    emoji,
    title: node.title,
    model: node.model,
    tier: node.tier,
    phaseColor: node.departmentColor || node.phaseColor,
    reportsTo: node.reportsTo,
    dimmed: false,
    level: node.level ?? null,
    levelTitle: node.levelTitle ?? null,
    yearsOfExperience: node.yearsOfExperience ?? null,
    status: node.status,
  }
}

function computeDepartmentLayout(
  allNodes: OrgChartNode[],
  departmentList: OrgChartData['departments'] = [],
): {
  rfNodes: Node[]
  rfEdges: Edge[]
} {
  // Rex (and anyone else without a manager) is a top leader. Everyone else
  // gets placed in their department column.
  const leaders = allNodes.filter(n => !n.reportsTo)
  const leaderIds = new Set(leaders.map(l => l.id))
  const members = allNodes.filter(n => !leaderIds.has(n.id))

  // Build a member-by-department lookup
  const byDepartment = new Map<string, OrgChartNode[]>()
  for (const m of members) {
    // Use '__unassigned__' so agents without a department are grouped explicitly
    // rather than silently dumped into 'engineering'
    const dept = m.department || '__unassigned__'
    if (!byDepartment.has(dept)) byDepartment.set(dept, [])
    byDepartment.get(dept)!.push(m)
  }

  // Departments to render — use the server-provided ordered list, skipping
  // any department whose only members are already rendered as leader nodes
  // (i.e. departments that are empty after separating out leaders).
  // This is data-driven — no hardcoded 'executive' string.
  const departments = departmentList
    .map(d => ({
      id: d.id,
      label: d.label,
      color: d.color,
      head: d.head,
      members: (byDepartment.get(d.id) || []).slice().sort((a, b) => {
        // Department head first, then leaders, then by level desc, then name
        if (a.id === d.head) return -1
        if (b.id === d.head) return 1
        if (a.tier === 'leadership' && b.tier !== 'leadership') return -1
        if (b.tier === 'leadership' && a.tier !== 'leadership') return 1
        if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0)
        return a.name.localeCompare(b.name)
      }),
    }))
    .filter(d => d.members.length > 0)

  // If any registered agents have no department assigned, add a virtual "Unassigned" column
  const unassignedMembers = byDepartment.get('__unassigned__') || []
  if (unassignedMembers.length > 0) {
    departments.push({
      id: '__unassigned__',
      label: 'Unassigned',
      color: '#6b7280',
      head: '',
      members: unassignedMembers.slice().sort((a, b) => a.name.localeCompare(b.name)),
    })
  }

  // Compute row widths
  const deptsRowWidth = departments.length * DEPT_WIDTH
    + Math.max(0, departments.length - 1) * DEPT_ROW_GAP
  const leadersRowWidth = leaders.length * LEADER_WIDTH
    + Math.max(0, leaders.length - 1) * LEADER_LEADER_GAP
  const canvasWidth = Math.max(deptsRowWidth, leadersRowWidth)

  // Y positions
  const leadersY = 0
  const deptsY = LEADER_HEIGHT + LEADER_DEPT_GAP

  const rfNodes: Node[] = []
  const rfEdges: Edge[] = []

  // Place leader nodes (Rex + any other top-level agent)
  const leadersStartX = (canvasWidth - leadersRowWidth) / 2
  const rexId = leaders[0]?.id
  leaders.forEach((leader, i) => {
    const x = leadersStartX + i * (LEADER_WIDTH + LEADER_LEADER_GAP)
    const { emoji, cleanName } = extractEmoji(leader.name)
    rfNodes.push({
      id: leader.id,
      type: 'orgLeader',
      position: { x, y: leadersY },
      data: {
        id: leader.id,
        name: cleanName,
        emoji,
        title: leader.title,
        model: leader.model,
        tier: leader.tier,
        phaseColor: leader.departmentColor || leader.phaseColor,
        description: leader.description,
        dimmed: false,
      } satisfies LeaderNodeData,
    })
  })

  // Place department columns
  const deptsStartX = (canvasWidth - deptsRowWidth) / 2
  departments.forEach((dept, i) => {
    const x = deptsStartX + i * (DEPT_WIDTH + DEPT_ROW_GAP)
    const memberCount = dept.members.length
    const height = DEPT_HEADER_HEIGHT
      + DEPT_PADDING_Y * 2
      + memberCount * MEMBER_ROW_HEIGHT
      + Math.max(0, memberCount - 1) * MEMBER_ROW_GAP

    rfNodes.push({
      id: `dept-${dept.id}`,
      type: 'orgDept',
      position: { x, y: deptsY },
      data: {
        // Reuse phase* field names so OrgDepartmentNode renders unchanged
        phase: dept.id,
        phaseLabel: dept.label,
        phaseColor: dept.color,
        members: dept.members.map(toMemberInfo),
        width: DEPT_WIDTH,
        height,
        dimmed: false,
      } satisfies DepartmentNodeData,
    })

    // Edge from Rex to each department
    if (rexId) {
      rfEdges.push({
        id: `e-${rexId}-dept-${dept.id}`,
        source: rexId,
        target: `dept-${dept.id}`,
        type: 'smoothstep',
        style: {
          stroke: dept.color,
          strokeWidth: 2.5,
          opacity: 0.55,
        },
      })
    }
  })

  return { rfNodes, rfEdges }
}

// ── Leader Node Component ────────────────────────────────────────────────────

function OrgLeaderNode({ data, selected }: { data: LeaderNodeData; selected: boolean }) {
  const { onSelect, selectedId } = useContext(OrgSelectContext)
  const isSelected = selected || selectedId === data.id
  const badge = MODEL_BADGES[data.model]

  return (
    <div
      className="transition-opacity duration-200"
      style={{ opacity: data.dimmed ? 0.2 : 1 }}
    >
      <button
        onClick={(e) => {
          e.stopPropagation()
          onSelect(data.id)
        }}
        className={`relative rounded-2xl border-2 bg-surface shadow-lg transition-all duration-200 text-left block
          ${isSelected
            ? 'ring-2 ring-accent/40 ring-offset-2 ring-offset-bg border-accent'
            : 'border-border hover:border-accent/40 hover:shadow-xl'
          }`}
        style={{ width: LEADER_WIDTH, height: LEADER_HEIGHT }}
      >
        {/* Crown badge */}
        <div className="absolute -top-2.5 left-4 flex items-center gap-1 px-2 py-0.5 rounded-full bg-gradient-to-r from-amber-500 to-yellow-500 text-white shadow-sm">
          <Crown className="w-2.5 h-2.5" />
          <span className="text-[9px] font-bold uppercase tracking-wider">
            {data.tier === 'leadership' ? 'Leadership' : 'Advisor'}
          </span>
        </div>

        <div className="px-4 pt-4 pb-3 flex items-center gap-3 h-full">
          <AgentIcon name={data.name} uid={`leader-${data.id}`} size={48} global />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              {data.emoji && <span className="text-base leading-none">{data.emoji}</span>}
              <span className="text-[15px] font-bold truncate">{data.name}</span>
              {badge && (
                <span
                  className="text-[8px] px-1.5 py-0.5 rounded-full font-bold shrink-0"
                  style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
                >
                  {badge.label}
                </span>
              )}
            </div>
            <div className="text-[11px] text-text-muted truncate mt-0.5">{data.title}</div>
          </div>
        </div>
      </button>

      <Handle
        type="source"
        position={Position.Bottom}
        className="!w-2 !h-2 !bg-transparent !border-0"
      />
    </div>
  )
}

// ── Department Node Component ────────────────────────────────────────────────

function OrgDepartmentNode({ data }: { data: DepartmentNodeData; selected: boolean }) {

