function computeDepartmentLayout(
  allNodes: OrgChartNode[],
  departmentList: OrgChartData['departments'] = [],
): {
  rfNodes: Node[]
  rfEdges: Edge[]
} {
  // ── Layout shape ────────────────────────────────────────────────────────────
  // Row 0 (y=0):                                  [ Rex (LEADERSHIP) ]
  // Row 1 (y=LEADER_HEIGHT + DEPT_HEAD_ROW_GAP):  [ Arya ] [ Nova ] [ Quill ] ...
  // Row 2 (y=above + LEADER_HEIGHT + LEADER_DEPT_GAP):  Engineering | Research | ...
  //                                                     ┌──────────┐ ┌──────────┐
  //                                                     │ Koda     │ │ Scout    │
  //                                                     │ Dato     │ │ ...      │
  //                                                     │  └ pod-b-db (indent)  │
  //                                                     └──────────┘ └──────────┘
  //
  // Strict leader rule: ONLY agents with `tier === 'leadership' && !reportsTo`
  // sit at Row 0. Everyone else lands in a department column or "Unassigned".

  // Index nodes by id and by manager (reportsTo) — used for tree traversal.
  const byId = new Map<string, OrgChartNode>()
  const byManager = new Map<string | null, OrgChartNode[]>()
  for (const n of allNodes) {
    byId.set(n.id, n)
    const key = n.reportsTo || null
    if (!byManager.has(key)) byManager.set(key, [])
    byManager.get(key)!.push(n)
  }

  const rex = allNodes.find(n => n.tier === 'leadership' && !n.reportsTo) || null

  // Department-head ids per the registered department list (e.g. arya, nova, …).
  const deptHeadIds = new Set(
    departmentList.map(d => d.head).filter((h): h is string => !!h)
  )

  // Departments to render — server-ordered. Department head is rendered as a
  // Row 1 leader card and EXCLUDED from the column member list.
  const sortMembers = (a: OrgChartNode, b: OrgChartNode) => {
    if (a.tier === 'leadership' && b.tier !== 'leadership') return -1
    if (b.tier === 'leadership' && a.tier !== 'leadership') return 1
    if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0)
    return a.name.localeCompare(b.name)
  }

  // Build an ordered, indented member list for one department column. Walks
  // the reportsTo tree so sub-managers (e.g. dato) precede their reports
  // (pod-b-db indented one level under dato).
  const buildColumnMembers = (deptId: string, headId: string | null): MemberInfo[] => {
    const out: MemberInfo[] = []
    const seen = new Set<string>()

    const sameDept = (n: OrgChartNode) => (n.department || '__unassigned__') === deptId

    // Direct reports of the dept head (or top-of-column if no head).
    const roots = (byManager.get(headId) || [])
      .filter(sameDept)
      .filter(n => n.id !== headId)
      .slice()
      .sort(sortMembers)

    const visit = (node: OrgChartNode, depth: number) => {
      if (seen.has(node.id)) return
      seen.add(node.id)
      out.push(toMemberInfo(node, depth))
      const children = (byManager.get(node.id) || [])
        .filter(sameDept)
        .slice()
        .sort(sortMembers)
      for (const c of children) visit(c, depth + 1)
    }

    for (const r of roots) visit(r, 0)

    // Catch any orphan in this department whose reportsTo points outside the
    // department (or is null) — render them at depth 0 so nobody is dropped.
    const orphans = allNodes
      .filter(sameDept)
      .filter(n => n.id !== headId && !seen.has(n.id))
      .slice()
      .sort(sortMembers)
    for (const o of orphans) visit(o, 0)

    return out
  }

  const departments = departmentList
    .map(d => ({
      id: d.id,
      label: d.label,
      color: d.color,
      head: d.head ? byId.get(d.head) || null : null,
      members: buildColumnMembers(d.id, d.head || null),
    }))
    .filter(d => d.head || d.members.length > 0)

  // Unassigned column: agents whose `department` is missing or 'unassigned',
  // and who aren't Rex or a dept head. These are typically newly-seeded
  // probation/pending agents waiting on HR triage.
  const renderedIds = new Set<string>()
  if (rex) renderedIds.add(rex.id)
  for (const d of departments) {
    if (d.head) renderedIds.add(d.head.id)
    for (const m of d.members) renderedIds.add(m.id)
  }
  const unassigned = allNodes
    .filter(n => !renderedIds.has(n.id))
    .slice()
    .sort(sortMembers)
  if (unassigned.length > 0) {
    departments.push({
      id: '__unassigned__',
      label: 'Unassigned',
      color: '#6b7280',
      head: null,
      members: unassigned.map(n => toMemberInfo(n, 0)),
    })
  }

  // ── Position math ───────────────────────────────────────────────────────────
  const deptCount = departments.length
  const deptsRowWidth = deptCount * DEPT_WIDTH
    + Math.max(0, deptCount - 1) * DEPT_ROW_GAP
  const canvasWidth = Math.max(deptsRowWidth, LEADER_WIDTH)

  const rexY = 0
  const deptHeadsY = LEADER_HEIGHT + DEPT_HEAD_ROW_GAP
  const deptColsY = deptHeadsY + LEADER_HEIGHT + LEADER_DEPT_GAP

  const deptsStartX = (canvasWidth - deptsRowWidth) / 2

  const rfNodes: Node[] = []
  const rfEdges: Edge[] = []

  // Row 0 — Rex
  if (rex) {
    const { emoji, cleanName } = extractEmoji(rex.name)
    rfNodes.push({
      id: rex.id,
      type: 'orgLeader',
      position: { x: (canvasWidth - LEADER_WIDTH) / 2, y: rexY },
      data: {
        id: rex.id,
        name: cleanName,
        emoji,
        title: rex.title,
        model: rex.model,
        tier: rex.tier,
        phaseColor: rex.departmentColor || rex.phaseColor,
        description: rex.description,
        dimmed: false,
      } satisfies LeaderNodeData,
    })
  }

  // Row 1 + Row 2 — dept heads (above) and dept columns (below).
  departments.forEach((dept, i) => {
    const colX = deptsStartX + i * (DEPT_WIDTH + DEPT_ROW_GAP)
    const memberCount = dept.members.length
    const colHeight = DEPT_HEADER_HEIGHT
      + DEPT_PADDING_Y * 2
      + memberCount * MEMBER_ROW_HEIGHT
      + Math.max(0, memberCount - 1) * MEMBER_ROW_GAP

    // Department head leader card on Row 1, centered above its column.
    let deptHeadCardId: string | null = null
    if (dept.head) {
      deptHeadCardId = dept.head.id
      const { emoji, cleanName } = extractEmoji(dept.head.name)
      const headX = colX + (DEPT_WIDTH - LEADER_WIDTH) / 2
      rfNodes.push({
        id: dept.head.id,
        type: 'orgLeader',
        position: { x: headX, y: deptHeadsY },
        data: {
          id: dept.head.id,
          name: cleanName,
          emoji,
          title: dept.head.title,
          model: dept.head.model,
          tier: dept.head.tier,
          phaseColor: dept.head.departmentColor || dept.head.phaseColor,
          description: dept.head.description,
          dimmed: false,
        } satisfies LeaderNodeData,
      })

      // Edge: Rex → dept head
      if (rex) {
        rfEdges.push({
          id: `e-${rex.id}-${dept.head.id}`,
          source: rex.id,
          target: dept.head.id,
          type: 'smoothstep',
          style: { stroke: dept.color, strokeWidth: 2.5, opacity: 0.6 },
        })
      }
    }

    // Department column on Row 2.
    const deptNodeId = `dept-${dept.id}`
    rfNodes.push({
      id: deptNodeId,
      type: 'orgDept',
      position: { x: colX, y: deptColsY },
      data: {
        // Reuse phase* field names so OrgDepartmentNode renders unchanged.
        phase: dept.id,
        phaseLabel: dept.label,
        phaseColor: dept.color,
        members: dept.members,
        width: DEPT_WIDTH,
        height: colHeight,
        dimmed: false,
      } satisfies DepartmentNodeData,
    })

    // Edge: dept head → its column.  If no head (Unassigned), connect Rex
    // directly to the column so it doesn't float orphaned.
    const edgeSource = deptHeadCardId || rex?.id
    if (edgeSource) {
      rfEdges.push({
        id: `e-${edgeSource}-${deptNodeId}`,
        source: edgeSource,
        target: deptNodeId,
        type: 'smoothstep',
        style: {
          stroke: dept.color,
          strokeWidth: 2,
          opacity: deptHeadCardId ? 0.55 : 0.35,
          strokeDasharray: deptHeadCardId ? undefined : '4 4',
        },
      })
    }
  })

  return { rfNodes, rfEdges }
}

